Function made <- MakeAdder(amount As Integer)
  Define base As Integer <- amount;
  Define made As Function(Integer) As Integer <- Function(x As Integer) As Integer
    Return x + base;
  EndFunction;
  base <- 0;
EndFunction

Algorithm Sums
  Define n, x As Integer;
  Read n;
  Read x;
  Define add As Function(Integer) As Integer <- MakeAdder(n);
  Write add(x);
EndAlgorithm

